// HTTPStatusCoder is an interface that errors can implement to produce status code for HTTP response
type HTTPStatusCoder interface {
	HTTPStatus() int
}

// StatusCode returns status code from err if it implements HTTPStatusCoder interface.
// If err does not implement the interface, it returns 0.
func StatusCode(err error) int {
	var sc HTTPStatusCoder
	if errors.As(err, &sc) {
		return sc.StatusCode()
	}
	return 0
	Message string `json:"message"`
	err     error
}

// HTTPStatus returns status code for HTTP response
func (he *HTTPError) HTTPStatus() int {
	return he.Code
}

type httpError struct {
	code int
}

func (he httpError) HTTPStatus() int {
	return he.code
}
}

// HTTPStatus returns status code for HTTP response, implementing HTTPStatusCoder interface.
func (pe *ProblemError) HTTPStatus() int {
	return pe.Status
}

func NewHTTPError(code int, message string) *HTTPError
